import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function AddUser() {
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const navigate = useNavigate();

  const handleSave = async () => {
    const mobile = localStorage.getItem("mobile");

    if (!mobile) {
      alert("Mobile not found. Please verify OTP first.");
      return;
    }
    if (!name.trim() || !address.trim()) {
      alert("Enter all details");
      return;
    }

    try {
      const response = await axios.post(
        `http://localhost:8080/otp/addUser?mobile=${mobile}&name=${name}&address=${address}`
      );
      alert(response.data);

      localStorage.removeItem("mobile");
      setName("");
      setAddress("");

      navigate("/categories");
    } catch (error) {
      alert("Failed to save user");
    }
  };

  return (
    <div className="container mt-5">
      <div className="card p-4 shadow-lg mx-auto" style={{ maxWidth: "450px" }}>
        <h2 className="text-center mb-3">Add User Details</h2>

        <input
          type="text"
          className="form-control mb-3"
          placeholder="Enter Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />

        <input
          type="text"
          className="form-control mb-3"
          placeholder="Enter Address"
          value={address}
          onChange={(e) => setAddress(e.target.value)}
        />

        <p className="text-muted">Mobile: {localStorage.getItem("mobile")}</p>

        <button className="btn btn-dark w-100 fw-bold" onClick={handleSave}>
          Save User
        </button>
      </div>
    </div>
  );
}
